	@Override
	public boolean usePreparedQuery(StatementPattern stmt, QueryInfo queryInfo) {
		// Local query preparation owns the typed operands; callers must not serialize them into SPARQL.
		if (EndpointIdentity.localStore(endpoint) != null) {
			return false;
		}
		// we use a prepared query for variable GRAPH patterns (=> cannot be done
		// using the Repository API).
		if (stmt.getContextVar() != null && !stmt.getContextVar().hasValue()) {
			return true;
		}
		Dataset ds = queryInfo.getDataset();
		if (ds != null) {

			// if FROM NAMED is used we rely on a prepared query
			return !ds.getNamedGraphResources().isEmpty();
		}

		// in all other cases: try to use the Repository API
		return false;
	}

	private boolean requiresPreparedQuery(StatementPattern statement, Dataset dataset) {
		return statement instanceof TripleRefStatementPattern || statement.getContextVar() != null
				|| dataset != null && (!dataset.getNamedGraphResources().isEmpty() || dataset.isExplicitReadDataset());
	}

